


export type DeliveryProfileInput = { /** Current delivery requirement and grouping policy. */ "configuration": { /** Required as a non-empty unique list when requirement is required. quote accepts shipment, pickup, and local_delivery. manual accepts digital and service. */ "allowed_types"?: Array<"shipment" | "pickup" | "local_delivery" | "digital" | "service">; /** Required for quote resolution and forbidden when requirement is none or resolution_mode is manual. Controls which delivery obligations can share a choice group. */ "combination_policy"?: "combine_when_compatible" | "separate_profile" | "separate_line_item" | "fulfill_alone"; /** Optional physical dimensions used by quote planning. Forbidden when requirement is none or resolution_mode is manual. */ "dimensions"?: { /** Use an exact numeric string, not a floating-point number. Format: int64. */ "height": string; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "length": string; "unit": string; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "width": string; }; /** Required for quote resolution and forbidden for none or manual resolution. fixed_location requires location_id. inventory_routing forbids location_id and applies only to tracked inventory. method_origin forbids location_id. */ "origin_policy"?: { "location_id"?: string; "type": "fixed_location" | "inventory_routing" | "method_origin"; }; /** Whether delivery planning applies. none forbids every other configuration field. required also requires resolution_mode and allowed_types, plus the fields required by that resolution mode. */ "requirement": "none" | "required"; /** Required when requirement is required. quote plans physical delivery and requires origin_policy, combination_policy, and splitting_policy. manual supports digital and service items and forbids physical planning fields. */ "resolution_mode"?: "quote" | "manual"; /** Required for quote resolution and forbidden when requirement is none or resolution_mode is manual. Controls whether a line item quantity can be split across delivery assignments. */ "splitting_policy"?: "whole_line_item" | "quantity_split_allowed"; /** Optional physical weight used by quote planning. Forbidden when requirement is none or resolution_mode is manual. */ "weight"?: { /** Weight unit. Use gram, kilogram, ounce, or pound. */ "unit": "gram" | "kilogram" | "ounce" | "pound"; /** Use an exact numeric string, not a floating-point number. Format: int64. */ "value": string; }; }; /** Time the profile was created. Format: date-time. */ "created_at": string | globalThis.Date; /** Immutable revision used for new line-item snapshots. */ "current_delivery_profile_revision_id": string; /** Stable delivery profile ID. */ "delivery_profile_id": string; /** Read-only catalog and delivery-method compatibility diagnostics. */ "diagnostics"?: never; /** Caller-owned identifier for this resource in an external system. maxLength: 255. */ "external_reference_id"?: string; /** Caller-owned metadata. */ "metadata"?: Record<string, string>; /** Merchant-facing profile name. */ "name": string; /** Current profile lifecycle status. */ "status": "inactive" | "active" | "archived" | "revoked"; /** Time the profile last changed. Format: date-time. */ "updated_at": string | globalThis.Date; /** Optimistic-concurrency version for profile writes. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 1. */ "version": string; };
